<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>TLC Walk-in Clinic | Bethany, OK</title>

    <!-- Google Fonts: Montserrat & Open Sans -->
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Montserrat:wght@500;600;700;800&family=Open+Sans:wght@400;600&display=swap" rel="stylesheet">

    <!-- FontAwesome -->
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0/css/all.min.css">

    <style>
        /* --- THEME VARIABLES (White, Red, Black - "Curate Health" Style) --- */
        :root {
            --red: #D32F2F;
            --red-light: #FFEBEE;
            --black: #111111;
            --grey-light: #F7F7F7;
            --grey-text: #555555;
            --white: #FFFFFF;

            /* Design Tokens */
            --radius: 24px; /* The key to the "Curate" look */
            --shadow: 0 10px 30px rgba(0,0,0,0.05);
            --container: 1200px;
        }

        /* --- RESET --- */
        * { box-sizing: border-box; margin: 0; padding: 0; }

        body {
            font-family: 'Open Sans', sans-serif;
            background-color: var(--white);
            color: var(--black);
            line-height: 1.6;
            overflow-x: hidden;
        }

        h1, h2, h3, h4 {
            font-family: 'Montserrat', sans-serif;
            color: var(--black);
            letter-spacing: -0.5px; /* Tighter spacing for modern look */
        }

        a { text-decoration: none; color: inherit; transition: 0.3s; }
        img { width: 100%; height: 100%; object-fit: cover; display: block; }

        /* --- UTILITIES --- */
        .container {
            max-width: var(--container);
            margin: 0 auto;
            padding: 0 20px;
        }

        .pill-btn {
            display: inline-flex;
            align-items: center;
            gap: 10px;
            padding: 12px 30px;
            border-radius: 50px; /* Pill shape */
            font-weight: 600;
            font-family: 'Montserrat', sans-serif;
            font-size: 0.9rem;
            cursor: pointer;
            transition: all 0.3s ease;
        }

        .btn-black { background: var(--black); color: var(--white); }
        .btn-black:hover { background: var(--red); transform: translateY(-2px); }

        .btn-white { background: var(--white); color: var(--black); }
        .btn-white:hover { background: var(--grey-light); }

        .btn-red { background: var(--red); color: var(--white); }
        .btn-red:hover { background: var(--black); }

        .section-spacer { padding: 80px 0; }

        /* --- TICKER BAR (Like the top bar in image) --- */
        .ticker-bar {
            background-color: var(--red);
            color: var(--white);
            padding: 8px 0;
            text-align: center;
            font-size: 0.85rem;
            font-weight: 600;
            font-family: 'Montserrat', sans-serif;
        }

        /* --- HEADER --- */
        header {
            padding: 20px 0;
            background: var(--white);
            position: sticky;
            top: 0;
            z-index: 100;
            border-bottom: 1px solid rgba(0,0,0,0.05);
        }

        .nav-flex {
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .logo {
            font-size: 1.4rem;
            font-weight: 800;
            color: var(--black);
            display: flex;
            align-items: center;
            gap: 8px;
        }
        .logo i { color: var(--red); }

        .desktop-nav { display: flex; gap: 30px; }
        .desktop-nav a { font-weight: 600; font-size: 0.95rem; color: var(--black); }
        .desktop-nav a:hover { color: var(--red); }

        /* --- HERO SECTION (Curate Style) --- */
        .hero-wrapper {
            margin-top: 20px;
            padding: 0 20px; /* Spacing for the rounded container effect */
        }

        .hero-card {
            background-color: var(--grey-light);
            border-radius: var(--radius);
            overflow: hidden;
            position: relative;
            min-height: 550px;
            display: flex;
            align-items: center;
        }

        .hero-bg {
            position: absolute;
            top: 0; left: 0; right: 0; bottom: 0;
            background: url('https://images.unsplash.com/photo-1571019614242-c5c5dee9f50b?ixlib=rb-1.2.1&auto=format&fit=crop&w=1950&q=80') center/cover;
            filter: brightness(0.9);
        }

        /* Gradient overlay to make text pop */
        .hero-overlay {
            position: absolute;
            top: 0; left: 0; right: 0; bottom: 0;
            background: linear-gradient(to right, rgba(0,0,0,0.7) 0%, rgba(0,0,0,0) 60%);
        }

        .hero-content {
            position: relative;
            z-index: 2;
            max-width: 600px;
            padding: 60px;
            color: var(--white);
        }

        .hero-content h1 {
            font-size: 3.5rem;
            color: var(--white);
            line-height: 1.1;
            margin-bottom: 20px;
        }

        .hero-content p { font-size: 1.1rem; margin-bottom: 30px; opacity: 0.9; }

        .hero-badge {
            display: inline-block;
            background: rgba(255,255,255,0.2);
            backdrop-filter: blur(10px);
            padding: 8px 16px;
            border-radius: 30px;
            font-size: 0.8rem;
            margin-bottom: 20px;
            border: 1px solid rgba(255,255,255,0.3);
        }

        /* --- HOW IT WORKS (Simple Steps) --- */
        .steps-section { padding: 80px 0; text-align: center; }
        .steps-grid {
            display: flex;
            justify-content: center;
            gap: 50px;
            margin-top: 40px;
            flex-wrap: wrap;
        }

        .step-item { max-width: 250px; }
        .step-img {
            width: 120px; height: 120px;
            border-radius: 50%; /* Circle images like reference */
            margin: 0 auto 20px;
            overflow: hidden;
            border: 3px solid var(--grey-light);
        }
        .step-item h4 { margin-bottom: 10px; }
        .step-item p { font-size: 0.9rem; color: var(--grey-text); }

        /* --- BENTO GRID (Services) --- */
        /* This mimics the "Get a treatment plan for" section */
        .bento-section { background: var(--white); }

        .grid-header {
            display: flex;
            justify-content: space-between;
            align-items: end;
            margin-bottom: 40px;
        }

        .bento-grid {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            grid-template-rows: repeat(2, 280px);
            gap: 20px;
        }

        .bento-card {
            border-radius: var(--radius);
            overflow: hidden;
            position: relative;
            transition: transform 0.3s;
            cursor: pointer;
        }

        .bento-card:hover { transform: scale(1.02); }

        /* Image styling within card */
        .bento-card img { transition: 0.5s; }
        .bento-card:hover img { transform: scale(1.1); }

        /* The little pill label on the card */
        .card-label {
            position: absolute;
            bottom: 20px;
            left: 20px;
            background: var(--white);
            color: var(--black);
            padding: 8px 20px;
            border-radius: 30px;
            font-weight: 700;
            font-size: 0.85rem;
            box-shadow: 0 4px 10px rgba(0,0,0,0.2);
        }

        .card-arrow {
            position: absolute;
            bottom: 20px;
            right: 20px;
            width: 35px; height: 35px;
            background: var(--white);
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            color: var(--black);
        }

        /* Grid Spanning */
        .span-2 { grid-column: span 2; }

        /* --- FEATURE SECTION (Weight Loss / DOT) --- */
        /* Matches the Green/Dark card in reference, but using Black/Red */
        .feature-wrapper {
            padding: 20px; /* Spacing for rounded container */
        }

        .feature-card {
            background-color: var(--black);
            color: var(--white);
            border-radius: var(--radius);
            padding: 60px;
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 60px;
            align-items: center;
            position: relative;
            overflow: hidden;
        }

        /* Abstract circle decoration */
        .feature-card::after {
            content: '';
            position: absolute;
            top: -50%;
            right: -10%;
            width: 600px;
            height: 600px;
            border: 1px solid rgba(255,255,255,0.1);
            border-radius: 50%;
        }

        .feature-text h2 { color: var(--white); font-size: 2.5rem; margin-bottom: 20px; }
        .feature-text p { color: #ccc; margin-bottom: 30px; font-size: 1.1rem; }

        .feature-img-box {
            background: var(--grey-light);
            height: 400px;
            border-radius: var(--radius);
            overflow: hidden;
            position: relative;
        }

        /* --- PRICING TABLE (Clean) --- */
        .pricing-card {
            background: var(--grey-light);
            padding: 40px;
            border-radius: var(--radius);
            margin-top: 40px;
        }
        .price-row {
            display: flex;
            justify-content: space-between;
            padding: 15px 0;
            border-bottom: 1px solid #ddd;
        }
        .price-row:last-child { border-bottom: none; }
        .price-tag { font-weight: 700; color: var(--red); }

        /* --- FOOTER --- */
        footer {
            background: var(--grey-light);
            padding: 80px 0 30px;
            margin-top: 80px;
            border-top-left-radius: var(--radius);
            border-top-right-radius: var(--radius);
        }

        .footer-grid {
            display: grid;
            grid-template-columns: 1.5fr 1fr 1fr 1fr;
            gap: 40px;
        }

        .footer-col h5 { font-size: 1.1rem; margin-bottom: 20px; color: var(--black); }
        .footer-col p, .footer-col a { 
            color: var(--grey-text); 
            font-size: 0.9rem; 
            display: block; 
            margin-bottom: 10px; 
        }

        /* --- RESPONSIVE --- */
        @media (max-width: 900px) {
            .bento-grid { grid-template-columns: repeat(2, 1fr); }
            .feature-card { grid-template-columns: 1fr; padding: 40px; }
            .hero-content h1 { font-size: 2.5rem; }
            .footer-grid { grid-template-columns: 1fr 1fr; }
        }

        @media (max-width: 600px) {
            .bento-grid { grid-template-columns: 1fr; grid-template-rows: auto; }
            .desktop-nav { display: none; } /* Simplified for this demo */
            .hero-content { padding: 30px; }
            .steps-grid { flex-direction: column; align-items: center; }
            .footer-grid { grid-template-columns: 1fr; }
        }
    </style>
</head>
